import {
  boldBase64,
  boldItalicBase64,
  italicBase64,
  pdfFontNames,
  regularBase64,
} from './pdfFontData';

// Liberation Sans (metric-compatible with Arial) embedded as base64 so PDF
// export works fully offline without fetch/CSP issues. Generated by
// scripts/generate-pdf-fonts.mjs from src/assets/fonts/*.ttf.
export const pdfFonts = {
  regular: { name: pdfFontNames.regular, base64: () => regularBase64 },
  bold: { name: pdfFontNames.bold, base64: () => boldBase64 },
  italic: { name: pdfFontNames.italic, base64: () => italicBase64 },
  boldItalic: { name: pdfFontNames.boldItalic, base64: () => boldItalicBase64 },
};
